import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";

const inputUrl = new URL("../../../api/v1/prices.json", import.meta.url);
const outputUrl = new URL("../src/generated/bundled.ts", import.meta.url);
const document = JSON.parse(await readFile(inputUrl, "utf8"));

if (!document.generated_at || !Array.isArray(document.models)) {
  throw new Error("api/v1/prices.json does not match the expected dataset shape");
}

const output = `// Generated by scripts/refresh-bundle.mjs. Do not edit by hand.\n` +
  `export const bundledSnapshotGeneratedAt = ${JSON.stringify(document.generated_at)};\n` +
  `export const bundledPriceDocument: unknown = ${JSON.stringify(document, null, 2)};\n`;

await mkdir(dirname(fileURLToPath(outputUrl)), { recursive: true });
await writeFile(outputUrl, output, "utf8");
console.log(`Bundled ${document.models.length} models from dataset ${document.generated_at}.`);
